class Cache:
    def __init__(self):
        self.data = {}

    def get(self, key):
        return self.data.get(key)

    def put(self, key, value):
        self.data[key] = value

    def invalidate(self, key):
        self.data.pop(key, None)

files.aggregate.py:
def total_by_key(rows):
    totals = {}
    for row in rows:
        totals[row["k"]] = totals.get(row["k"], 0) + row["v"]
    for key in list(totals):
        if totals[key] == 0:
            del totals[key]
    return totals

